mapper.update:
UPDATE ocr_job
SET status = 'RUNNING', attempt_count = attempt_count + 1, started_at = #{now},
    next_retry_at = NULL, updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING'
  AND (next_retry_at IS NULL OR next_retry_at <= #{now})

UPDATE ocr_job
SET status = 'PENDING', error_code = #{errorCode}, next_retry_at = #{nextRetryAt}, updated_at = #{now}
WHERE id = #{id} AND status = 'RUNNING'

mapper.select:
SELECT  FROM ocr_job
WHERE status = 'RUNNING' AND started_at < #{startedBefore}
ORDER BY id
LIMIT #{limit}
